/**
 * EVALUADOR DE ACTIVOS (BRANCHING) — CommunityLab
 *
 * Entrada: resumen consolidado del lote.
 * Salida: decisiones de generación y evidencias clasificadas.
 *
 * Override explícito: opciones.generar_activos.
 * Sin override: se aplican las reglas automáticas.
 */

const input = $input.first()?.json ?? {};

const interacciones = Array.isArray(input.interacciones_analizadas)
  ? input.interacciones_analizadas
  : [];

const opciones = input.opciones ?? {};

const ACTIVOS_VALIDOS = [
  "LINKEDIN",
  "NEWSLETTER",
  "FAQ"
];

const testimoniosLogros = [];
const preguntasDudas = [];

// 1. Clasificar las interacciones por tipo de insight y sentimiento.
for (const item of interacciones) {
  const analisis = item.analisis ?? {};

  const tipoInsight = String(
    analisis.tipo_insight ?? ""
  ).trim().toLowerCase();

  const sentimiento = String(
    analisis.sentimiento ?? ""
  ).trim().toLowerCase();

  const esTestimonioOLogro =
    tipoInsight.includes("testimonio") ||
    tipoInsight.includes("logro");

  const esPositivo = sentimiento.includes("positi");

  const esPreguntaODuda =
    tipoInsight.includes("pregunta") ||
    tipoInsight.includes("duda") ||
    tipoInsight.includes("tecnica");

  if (esTestimonioOLogro && esPositivo) {
    testimoniosLogros.push(item);
  }

  if (esPreguntaODuda) {
    preguntasDudas.push(item);
  }
}

// 2. Determinar si hay un override explícito válido.
const overrideSolicitado =
  Array.isArray(opciones.generar_activos) &&
  opciones.generar_activos.length > 0;

let activosSolicitados;

if (overrideSolicitado) {
  activosSolicitados = [
    ...new Set(
      opciones.generar_activos
        .filter(valor => typeof valor === "string")
        .map(valor => valor.trim().toUpperCase())
        .filter(valor => ACTIVOS_VALIDOS.includes(valor))
    )
  ];
} else {
  activosSolicitados = [];

  if (testimoniosLogros.length > 0) {
    activosSolicitados.push("LINKEDIN", "NEWSLETTER");
  }

  if (preguntasDudas.length > 0) {
    activosSolicitados.push("FAQ");
  }
}

// 3. Construir una salida consistente para los siguientes nodos.
return [
  {
    json: {
      id_lote: input.id_lote ?? null,
      origen_comunidad: input.origen_comunidad ?? null,
      periodo_referencia: input.periodo_referencia ?? null,
      opciones,

      resumen_comunidad: input.resumen_comunidad ?? {},

      decisiones_branching: {
        generar_linkedin:
          activosSolicitados.includes("LINKEDIN"),

        generar_newsletter:
          activosSolicitados.includes("NEWSLETTER"),

        generar_faq:
          activosSolicitados.includes("FAQ"),

        activos_solicitados: activosSolicitados,
        modo_decision: overrideSolicitado
          ? "override"
          : "automatico"
      },

      evidencias: {
        testimonios_logros: testimoniosLogros,
        preguntas_dudas: preguntasDudas
      }
    }
  }
];

